<script lang="ts">
 import {onMount} from 'svelte';
 import {formatNumber} from '../format';
 import {nodeChoices} from '../reality-client-options';
 import BehaviorEditor from '../components/BehaviorEditor.svelte';
 import NodeLimitEditor from '../components/NodeLimitEditor.svelte';
 import QuotaFields from '../components/QuotaFields.svelte';
 import MemberServices from '../components/MemberServices.svelte';
 import AppSelect from '../components/Select.svelte';
 import Icon from '../components/Icon.svelte';
 import Modal from '../components/Modal.svelte';
 import {demo,saveRow,getRow,removeRow,toast,errorMessage} from '../store.svelte';
 import type {Row} from '../data';

 let view=$state('grid'),search=$state(''),open=$state(false),editing=$state(false),busy=$state(false),error=$state(''),form=$state<Row>({id:''}),nodes=$state<string[]>([]),behavior=$state(''),allConfirmed=$state(false),source=$state('all'),nodeSearch=$state(''),aliases=$state(false);
 let actionOpen=$state(false),action=$state(''),target=$state<Row|null>(null),confirmed=$state(false),actionError=$state(''),services=$state(false);
 const kinds=[{key:'clash',label:'Clash'},{key:'surge',label:'Surge'},{key:'loon',label:'Loon'}];
 const plans=$derived(demo.data.plans.filter(p=>[p.name,p.description].join(' ').toLowerCase().includes(search.trim().toLowerCase())));
 const choices=$derived(nodeChoices(demo.data.nodes,nodes));
 const sources=$derived([...new Set(choices.available.map(n=>n.sourceId||'internal'))]);
 const visibleNodes=$derived(choices.available.filter(n=>(source==='all'||(n.sourceId||'internal')===source)&&[n.name,n.protocol,n.region].join(' ').toLowerCase().includes(nodeSearch.toLowerCase())));
 const activeNodes=$derived(nodes.length?choices.available.filter(n=>nodes.includes(n.id)):choices.available);
 const shownSelected=$derived(visibleNodes.length>0&&visibleNodes.every(n=>nodes.includes(n.id)));
 onMount(()=>{try{view=localStorage.getItem('aswired-plans-view')==='list'?'list':'grid';}catch{}});
 function setView(value:string){view=value;try{localStorage.setItem('aswired-plans-view',value);}catch{}}
 function sourceName(id:string){return id==='internal'?'内部节点':'远程：'+(demo.data.sources.find(s=>s.id===id)?.name??'已移除来源');}
 function resetLabel(p:Row){return p.reset?.includes('每月')?'每月 '+(p.resetDay||1)+' 日':p.reset==='购买周年日'?'每 '+(p.cycleDays||30)+' 天':'不重置';}
 function templateName(p:Row,key:string){const id=p.templateIds?.[key];return id?(demo.data.policies.find(t=>t.id===id)?.name??'模板已移除'):'系统默认';}
 function rate(p:Row){return Number(p.speed)>0?formatNumber(p.speed)+' Mbps':'不限速';}
 function connections(p:Row){return Number(p.connectionLimit)>0?p.connectionLimit+' 个连接':'连接数不限';}
 function usable(n:Row){return n.managedInbound===true;}
 async function edit(row?:Row){if(busy)return;busy=true;try{const fresh=row?await getRow('plans',row.id):null;editing=!!fresh;form=fresh?structuredClone(fresh):{id:crypto.randomUUID(),name:'',description:'',limit:100,cycleDays:30,reset:'每月指定日',resetDay:1,resetTimezone:'Asia/Shanghai',speed:0,connectionLimit:0,ipLimit:0,directionFactor:1,price:0,status:'启用',selfService:false,instructions:''};
  if(form.reset?.includes('每月'))form.reset='每月指定日';form.templateIds={...form.templateIds};form.nodeNames={...form.nodeNames};form.nodeTraffic=JSON.parse(JSON.stringify(form.nodeTraffic??{}));form.nodeLimits=JSON.parse(JSON.stringify(form.nodeLimits??{}));form.directionFactor=Number(form.directionFactor)||1;
  nodes=[...(fresh?.nodeIds??[])];behavior=form.behaviorLimits?JSON.stringify(form.behaviorLimits,null,2):'';aliases=Object.keys(form.nodeNames).length>0;allConfirmed=false;source='all';nodeSearch='';error='';open=true;
 }catch(cause){toast(errorMessage(cause));}finally{busy=false;}}
 function numericPatch(n:Row,group:string,key:string,input:HTMLInputElement){const entry={...form[group]?.[n.id]};if(input.value==='')delete entry[key];else entry[key]=input.valueAsNumber;const next={...form[group]};if(Object.keys(entry).length)next[n.id]=entry;else delete next[n.id];form[group]=next;}
 function aliasPatch(id:string,value:string){const next={...form.nodeNames};if(value.trim())next[id]=value;else delete next[id];form.nodeNames=next;}
 function selectVisible(){nodes=shownSelected?nodes.filter(id=>!visibleNodes.some(n=>n.id===id)):[...new Set([...nodes,...visibleNodes.map(n=>n.id)])];}
 async function save(){if(busy)return;error='';if(!nodes.length&&!allConfirmed){error='未选择节点表示全部受支持节点，请确认此范围';return;}busy=true;try{const limits=behavior.trim()?JSON.parse(behavior):null;if(limits&&(typeof limits!=='object'||Array.isArray(limits)))throw new Error('行为限速须为对象');await saveRow('plans',{...form,behaviorLimits:limits,nodes:nodes.length,nodeIds:nodes});open=false;toast('套餐模板已保存');}catch(cause){error=errorMessage(cause);}finally{busy=false;}}
 function ask(kind:string,p:Row){target=p;action=kind;confirmed=false;actionError='';actionOpen=true;}
 async function finish(){if(busy||!target)return;busy=true;actionError='';try{if(!confirmed)throw new Error('请先确认操作');if(action==='delete')await removeRow('plans',target.id);else{const latest=await getRow('plans',target.id);if(action==='publish'){latest.selfService=!target.selfService;if(latest.selfService)latest.status='启用';}else latest.status=target.status==='启用'?'停用':'启用';await saveRow('plans',latest);}actionOpen=false;toast('套餐已更新');}catch(cause){actionError=errorMessage(cause);}finally{busy=false;}}
</script>

{#snippet templates(p:Row)}<div class="template-summary">{#each kinds as kind}<span>{kind.label} · {templateName(p,kind.key)}</span>{/each}</div>{/snippet}
{#snippet actions(p:Row,compact=false)}<div class="plan-actions"><button class="button small" title={p.selfService?'下架申请':'发布申请'} aria-label={(p.selfService?'下架 ':'发布 ')+p.name+' 的申请'} disabled={busy} onclick={()=>ask('publish',p)}><Icon name="car"/>{#if !compact}{p.selfService?'下架申请':'发布申请'}{/if}</button><button class="button small" title="编辑套餐" aria-label={'编辑 '+p.name} disabled={busy} onclick={()=>edit(p)}><Icon name="edit"/>{#if !compact}编辑{/if}</button><button class="button small" title={p.status==='启用'?'停用套餐':'启用套餐'} aria-label={(p.status==='启用'?'停用 ':'启用 ')+p.name} disabled={busy} onclick={()=>ask('status',p)}><Icon name={p.status==='启用'?'pause':'play'}/></button><button class="button small danger" title="删除套餐" aria-label={'删除 '+p.name} disabled={busy} onclick={()=>ask('delete',p)}><Icon name="trash"/>{#if !compact}删除{/if}</button></div>{/snippet}

<div class="page-head"><div><div class="eyebrow">工作区 / 套餐</div><h1>套餐模板管理</h1><p>管理流量套餐模板，可在用户管理中为用户分配套餐。</p></div><div class="actions"><div class="view-switch" role="group" aria-label="套餐显示方式"><button class:active={view==='grid'} aria-label="卡片视图" aria-pressed={view==='grid'} onclick={()=>setView('grid')}><Icon name="grid"/></button><button class:active={view==='list'} aria-label="列表视图" aria-pressed={view==='list'} onclick={()=>setView('list')}><Icon name="list"/></button></div><button class="button primary" disabled={busy} onclick={()=>edit()}><Icon name="plus"/>创建套餐模板</button></div></div>
<div class="plan-search search-input"><Icon name="search"/><input aria-label="搜索套餐" placeholder="搜索套餐名称 / 描述" bind:value={search}/></div>
{#if !plans.length}<section class="card empty"><Icon name="package" size={30}/><h2>{search?'没有符合条件的套餐':'还没有套餐模板'}</h2><p>设置流量、周期和节点后，即可分配给用户。</p></section>
{:else if view==='grid'}<div class="plan-grid">{#each plans as p(p.id)}<article class="card package-card"><div class="package-heading"><h2>{p.name}</h2><span class="quota-badge">{p.limit?formatNumber(p.limit)+' GB':'不限流量'}</span></div>{#if p.description}<p class="description" title={p.description}>{p.description}</p>{/if}<dl><div><dt><Icon name="clock"/>计量周期</dt><dd>{p.cycleDays||30} 天</dd></div><div><dt><Icon name="refresh"/>默认重置日期</dt><dd>{resetLabel(p)}</dd></div><div><dt><Icon name="activity"/>流量统计</dt><dd>{Number(p.directionFactor)===2?'双向 ×2':'单向'}</dd></div><div><dt><Icon name="file"/>订阅模板</dt><dd>{@render templates(p)}</dd></div><div><dt><Icon name="sliders"/>限速配置</dt><dd>{rate(p)} · {connections(p)}</dd></div><div><dt><Icon name="network"/>关联节点</dt><dd><button class="node-count" onclick={()=>ask('nodes',p)}>{p.nodeIds?.length||'全部'} <Icon name="help" size={13}/></button></dd></div></dl><div class="plan-state"><span class:paused={p.status!=='启用'}>{p.status==='启用'?'启用':'停用'}</span><span>{p.selfService?'已开放申请':'未开放申请'}</span></div>{@render actions(p)}</article>{/each}</div>
{:else}<section class="card no-pad"><div class="table-scroll"><table aria-label="套餐模板列表"><thead><tr><th>套餐名</th><th>流量</th><th>周期</th><th>重置日</th><th>统计</th><th>模板</th><th>限速</th><th>节点</th><th>状态</th><th>操作</th></tr></thead><tbody>{#each plans as p(p.id)}<tr><td><strong>{p.name}</strong></td><td>{p.limit?formatNumber(p.limit)+' GB':'不限量'}</td><td>{p.cycleDays||30} 天</td><td>{resetLabel(p)}</td><td>{Number(p.directionFactor)===2?'双向 ×2':'单向'}</td><td>{@render templates(p)}</td><td>{rate(p)}<small>{connections(p)}</small></td><td><button class="node-count" onclick={()=>ask('nodes',p)}><Icon name="network"/>{p.nodeIds?.length||'全部'}</button></td><td>{p.status}<small>{p.selfService?'开放申请':'未发布'}</small></td><td>{@render actions(p,true)}</td></tr>{/each}</tbody></table></div></section>{/if}
<div class="support-actions"><a href="/members" class="button"><Icon name="users"/>前往用户管理分配套餐</a><button class="button" onclick={()=>services=!services}><Icon name="key"/>{services?'收起':'展开'}兑换码与申请核对</button></div>{#if services}<MemberServices admin/>{/if}

<Modal bind:open title={editing?'编辑套餐模板':'创建套餐模板'} description="设置套餐额度、订阅模板与关联节点" extraWide>
 <button type="button" class="icon-button close-editor" aria-label="关闭套餐编辑" disabled={busy} onclick={()=>open=false}><Icon name="x"/></button>
 <form onsubmit={e=>{e.preventDefault();void save();}}>
 <div class="plan-editor"><div class="plan-fields">
  <label class="field">套餐名称<input required maxlength="128" bind:value={form.name} placeholder="例如：基础套餐"/></label>
  <label class="field">描述<textarea maxlength="2000" bind:value={form.description} placeholder="套餐说明（可选）"></textarea></label>
  <label class="field">流量额度（GB）<input type="number" min="0" step="any" required bind:value={form.limit}/><small>0 表示不限流量</small></label>
  <label class="field">流量统计方式<AppSelect value={String(form.directionFactor)} onchange={v=>form.directionFactor=Number(v)} options={[{value:'1',label:'单向（默认）'},{value:'2',label:'双向 ×2'}]} aria-label="流量统计方式"/><small>按上传、下载计量记录计费；双向模式使用 2 倍倍率，仅影响后续用量。</small></label>
  {#each kinds as kind}<label class="field">{kind.label} 模板<AppSelect value={form.templateIds?.[kind.key]??''} onchange={v=>form.templateIds={...form.templateIds,[kind.key]:v}} options={[{value:'',label:'使用系统默认模板'},...demo.data.policies.filter(t=>(t.type||'Clash').toLowerCase()===kind.key).map(t=>({value:t.id,label:t.name}))]} aria-label={kind.label+' 模板'}/></label>{/each}
  <label class="field">计量周期（天）<input type="number" min="1" max="3660" step="1" required bind:value={form.cycleDays}/></label>
  <div class="reset-box"><div class="reset-heading"><strong>按月重置套餐流量</strong><button type="button" class="toggle" class:on={form.reset==='每月指定日'} role="switch" aria-checked={form.reset==='每月指定日'} aria-label="按月重置套餐流量" onclick={()=>form.reset=form.reset==='每月指定日'?'不重置':'每月指定日'}><i></i></button></div>{#if form.reset==='每月指定日'}<label class="field">默认重置日期（每月）<input type="number" min="1" max="31" step="1" required bind:value={form.resetDay}/></label><small>范围 1–31；当月没有该日期时，在当月最后一天重置。</small><label class="field">重置时区<input required bind:value={form.resetTimezone}/></label>{:else}<label class="field">重置策略<AppSelect bind:value={form.reset} options={['不重置','购买周年日']} aria-label="重置策略"/></label>{/if}</div>
  <div class="field-pair"><label class="field">限速（Mbps）<input type="number" min="0" step="any" bind:value={form.speed} placeholder="0 表示不限速"/></label><label class="field">连接数限制<input type="number" min="0" step="1" bind:value={form.connectionLimit} placeholder="0 表示不限制"/></label></div>
  <small>限速与连接数由受管 Agent 执行；同用户、同服务器按最高套餐权益合并。</small>
  <details><summary>更多设置</summary><div class="advanced"><label class="field">在线 IP 上限<input type="number" min="0" step="1" bind:value={form.ipLimit}/></label><label class="field">申请价格 / 元<input type="number" min="0" step="0.01" bind:value={form.price}/></label><label class="tag"><input type="checkbox" bind:checked={form.selfService}/>开放给工作区成员申请</label><label class="field">申请说明<textarea bind:value={form.instructions}></textarea></label><QuotaFields bind:row={form}/><BehaviorEditor bind:value={behavior}/><NodeLimitEditor bind:row={form}/></div></details>
 </div><div class="plan-node-panel"><div class="node-heading"><h3>关联节点</h3><div class="actions"><label class="alias-toggle"><input type="checkbox" bind:checked={aliases}/>套餐内节点名称</label><span>{nodes.length} / {choices.available.length}</span><button type="button" class="button small" disabled={!visibleNodes.length} onclick={selectVisible}>{shownSelected?'取消当前筛选选择':'全选当前筛选'}</button></div></div>
  <div class="source-filters" role="group" aria-label="节点来源筛选"><button type="button" class:active={source==='all'} onclick={()=>source='all'}>全部</button>{#each sources as id}<button type="button" class:active={source===id} onclick={()=>source=id}>{sourceName(id)}</button>{/each}</div>
  <div class="search-input node-search"><Icon name="search"/><input aria-label="搜索关联节点" placeholder="搜索节点名称 / 协议 / 地区" bind:value={nodeSearch}/></div>
  <div class="node-table table-scroll"><table aria-label="关联节点列表"><thead><tr><th>{aliases?'套餐内节点名称':'原节点名称'}</th><th>倍率</th><th>限速 Mbps</th><th>连接数</th><th>节点流量 GB</th></tr></thead><tbody>{#each visibleNodes as n(n.id)}<tr class:selected={nodes.includes(n.id)}><td><div class="node-identity"><input type="checkbox" aria-label={'选择 '+n.name} bind:group={nodes} value={n.id}/><span class="protocol-tag">{n.protocol}</span><span class="node-title">{n.name}<small>{n.region} · {usable(n)?'受管节点':'外部节点'}</small></span></div>{#if aliases}<input class="alias-input" aria-label={n.name+' 套餐内名称'} placeholder={n.name} value={form.nodeNames?.[n.id]??''} onchange={e=>aliasPatch(n.id,e.currentTarget.value)}/>{/if}</td>{#each [{group:'nodeTraffic',key:'multiplier',label:'倍率'},{group:'nodeLimits',key:'speed',label:'限速 Mbps'},{group:'nodeLimits',key:'connectionLimit',label:'连接数'},{group:'nodeTraffic',key:'limit',label:'节点流量 GB'}] as field}<td>{#if usable(n)}<input type="number" min="0" max="1000000000" step={field.key==='connectionLimit'?'1':'any'} disabled={nodes.length>0&&!nodes.includes(n.id)} aria-label={n.name+' '+field.label} placeholder={field.key==='limit'?'不限':'继承'} value={form[field.group]?.[n.id]?.[field.key]??''} onchange={e=>numericPatch(n,field.group,field.key,e.currentTarget)}/>{:else}<span class="muted" title="外部节点不由当前 Agent 计量或限速">—</span>{/if}</td>{/each}</tr>{:else}<tr><td colspan="5"><div class="empty">{choices.available.length?'没有匹配的节点':'暂无可用节点，请先在节点库添加节点。'}</div></td></tr>{/each}</tbody></table></div>
  {#if choices.unavailable.length}<details class="space-top"><summary>不可用的旧关联（{choices.unavailable.length}）</summary>{#each choices.unavailable as n}<label class="tag"><input type="checkbox" bind:group={nodes} value={n.id}/>{n.name}</label>{/each}</details>{/if}
  <p class="hint">未选择节点表示可使用全部受支持节点。当前范围 {activeNodes.length} 个；外部节点仅输出连接配置，不支持主控计量和限速。</p><p class="hint">节点额度按当前套餐周期的加权流量计算，耗尽后停止该节点凭据；0 为不限。倍率留空继承线路配置，0 为不计费。</p>
  {#if !nodes.length}<label class="tag space-top"><input type="checkbox" bind:checked={allConfirmed}/>确认套餐可使用全部受支持节点</label>{/if}
 </div></div>
 {#if error}<p class="error space-top" role="alert">{error}</p>{/if}<div class="modal-actions"><button type="button" class="button" disabled={busy} onclick={()=>open=false}>取消</button><button class="button primary" disabled={busy}>{busy?'保存中…':'保存套餐'}</button></div>
 </form>
</Modal>
<Modal bind:open={actionOpen} title={action==='delete'?'删除套餐':action==='publish'?(target?.selfService?'下架申请':'发布套餐申请'):action==='nodes'?'关联节点':'修改套餐状态'} description={target?.name??''}>
 {#if action==='nodes'}<div class="node-inspection">{#each nodeChoices(demo.data.nodes,target?.nodeIds??[]).available.filter(n=>!target?.nodeIds?.length||target.nodeIds.includes(n.id)) as n}<p><Icon name="network"/>{target?.nodeNames?.[n.id]||n.name}<small>{n.protocol}</small></p>{:else}<p class="muted">暂无可用节点</p>{/each}</div>
 {:else}<p>{action==='delete'?'删除套餐模板不可撤销；仍有关联订阅的套餐不能删除。':action==='publish'?(target?.selfService?'下架后不再接受新申请，已有套餐实例保持有效。':'发布到成员的申请套餐页面，由管理员人工核对后发放。'):target?.status==='启用'?'停用后，该套餐所有用户的订阅与受管凭据将停止使用。':'启用后恢复符合有效期和额度条件的套餐。'}</p><label class="tag space-top"><input type="checkbox" bind:checked={confirmed}/>确认{action==='delete'?'删除此套餐':'操作'}</label>{/if}
 {#if actionError&&action!=='nodes'}<p class="error" role="alert">{actionError}</p>{/if}<div class="modal-actions"><button class="button" disabled={busy} onclick={()=>actionOpen=false}>关闭</button>{#if action!=='nodes'}<button class="button" class:danger={action==='delete'} class:primary={action!=='delete'} disabled={busy||!confirmed} onclick={finish}>确认</button>{/if}</div>
</Modal>

<style>
 .close-editor{position:absolute;right:20px;top:20px}
 .page-head{align-items:flex-start}.page-head>.actions{flex-shrink:0}.view-switch{display:flex;border:1px solid var(--border);border-radius:7px;padding:3px;gap:3px}.view-switch button{padding:8px;border:0;border-radius:4px;background:transparent;color:var(--muted)}.view-switch button.active{color:var(--background);background:var(--primary)}.plan-search{max-width:380px;margin-bottom:20px}.plan-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.package-card{padding:22px;display:flex;flex-direction:column;gap:15px}.package-heading{display:flex;align-items:flex-start;justify-content:space-between;gap:12px}.package-heading h2{font-size:18px;overflow-wrap:anywhere}.quota-badge{white-space:nowrap;font-size:12px;color:var(--primary);background:color-mix(in srgb,var(--primary) 12%,transparent);padding:4px 8px;border-radius:4px}.description{color:var(--muted);font-size:12px;display:-webkit-box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}dl{display:grid;gap:13px;font-size:12px;margin:0;flex:1}dl>div{display:flex;justify-content:space-between;gap:18px}dt{display:flex;align-items:center;gap:8px;color:var(--muted);white-space:nowrap}dd{margin:0;text-align:right}.template-summary{display:flex;flex-direction:column;gap:3px;font-size:11px;overflow-wrap:anywhere}.plan-actions{display:flex;gap:7px;flex-wrap:wrap}.plan-actions .button{padding:5px 9px}.plan-state{display:flex;justify-content:space-between;font-size:11px;color:var(--muted)}.plan-state>span:first-child{color:var(--success)}.plan-state>span.paused{color:var(--warning)}.node-count{display:inline-flex;align-items:center;gap:6px;border:0;background:none;color:var(--foreground);padding:0}.table-scroll table{min-width:1120px}td,th{padding:14px 12px;font-size:12px}td small{display:block;color:var(--muted);font-size:10px;margin-top:4px}.support-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.plan-editor{display:grid;grid-template-columns:minmax(270px,340px) minmax(0,1fr);g