px;color:var(--muted);margin-top:4px}.alias-input{width:calc(100% - 22px);margin:8px 0 0 22px;font-size:11px}.node-table tr.selected{background:color-mix(in srgb,var(--primary) 6%,transparent)}.node-inspection{max-height:50vh;overflow:auto}.node-inspection p{display:flex;gap:10px;align-items:center;padding:10px 0;border-bottom:1px solid var(--line);font-size:13px}.node-inspection small{margin-left:auto;color:var(--muted)}summary{cursor:pointer;font-size:12px;color:var(--muted)}
